def move_task(list, old_index, new_index):
  if 0 <= old_index < len(list) and 0 <= new_index < len(list):
    task = list.pop(old_index)
    list.insert(new_index, task)
    return f"Task successfully moved. {len(list)} tasks remaining."
  else:
    return "Invalid index."

