def classify_by_angles(a,b,c):
  if (a + b <= c):
    return "invalid"
  if (c ** 2 == a ** 2 + b ** 2):
    return "right"
  elif (c ** 2 >= a ** 2 + b ** 2):
    return "obtuse"
  else:
    return "acute"

def classify_by_edges(a,b,c):
  if (a + b <= c):
    return "invalid"
  elif (a == b == c):
    return "equilateral"
  elif (a == b or b == c or a == c):
    return "isosceles"
  else:
    return "scalene"

def classify_by_angles(a, b, c):
  if a + b <= c:
    return 'invalid'
  elif a * a + b * b == c * c:
    return 'right'
  elif a * a + b * b > c * c:
    return 'acute'
  else:
    return 'obtuse'

def classify_by_edges(a, b, c):
  if a + b <= c:
    return 'invalid'
  elif a == b == c:
    return 'equilateral'
  elif a == b or b == c:
    return 'isosceles'
  else:
    return 'scalene'

def classify_by_angles(a:int,b:int,c:int):
  if a+b<=c:
    return 'invalid'
  else:
    if (c**2)== ((a**2) +(b**2)):
      return 'right'
    elif (c**2)>= ((a**2) +(b**2)):
      return 'obtuse'
    else:
      return 'acute'

def classify_by_edges(a:int,b:int,c:int)->str:
  if a+b<=c:
    return 'invalid'
  else:
    if a==b and b==c and c==a:
      return 'equilateral'
    elif (a==b and b!=c) or (a==c and a!=b) or (b==c and b!=a):
      return 'isosceles'
    else:
      return 'scalene'

def classify_by_angles(a, b, c):
    if a + b <= c:
        return "invalid"
    lhs = a * a + b * b
    rhs = c * c
    if rhs == lhs:
        return "right"
    elif rhs > lhs:
        return "obtuse"
    else:
        return "acute"

