    return "invalid"
  elif(c**2 == a**2 + b**2):
    return "right"
  elif(c**2 > a**2 + b**2):
    return "obtuse"
  elif(c**2 < a**2 + b**2):
    return "acute"

def classify_by_edges(a,b,c):
  if (a + b)<= c:
    return "invalid"
  elif(a == b == c):
    return "equilateral"
  elif((a == b) or (a == c) or (b ==c)):
    return "isosceles"
  else:
    return "scalene"

