def classify_by_angles(a, b, c):
    try:
        a, b, c = float(a), float(b), float(c)
    except (TypeError, ValueError):
        return "invalid"

    a, b, c = sorted((a, b, c))

    if a <= 0 or (a + b) <= c:
        return "invalid"

    lhs = c * c
    rhs = a * a + b * b

    if math.isclose(lhs, rhs, rel_tol=1e-9, abs_tol=1e-9):
        return "right"
    if lhs > rhs:
        return "obtuse"
    return "acute"

