def classify_by_angles(a, b, c):
    # Validity check first!
    if a <= 0 or b <= 0 or c <= 0:
        return "invalid"
    if a + b <= c or b + c <= a or a + c <= b:
        return "invalid"
    # Sort sides so z is largest
    x, y, z = sorted([a, b, c])
    if abs(x**2 + y**2 - z**2) < 1e-6:
        return "right"
    elif x**2 + y**2 < z**2:
        return "obtuse"
    else:
        return "acute"

def classify_by_edges(a, b, c):
    # Any side non-positive is invalid
    if a <= 0 or b <= 0 or c <= 0:
        return "invalid"
    # Triangle inequality: If ANY fails, invalid
    if a + b <= c or a + c <= b or b + c <= a:
        return "invalid"
    if a == b and b == c:
        return "equilateral"
    if a == b or b == c or a == c:
        return "isosceles"
    return "scalene"

