def classify_by_angles(a, b, c):
    """Classify a triangle by its angles using Pythagoras"""

    if a + b <= c:
        return "invalid"

    lhs = a**2 + b**2
    rhs = c**2

    if rhs == lhs:
        return "right"
    elif rhs > lhs:
        return "obtuse"
    else:
        return "acute"

