                penalty = 0.9
            if i[1] == 2:
                penalty = 0.75
            if i[1] == 3:
                penalty = 0.5
            if i[1] >= 4:
                penalty = 0
            score =score + i[0] * penalty
        avg_score = score / len(l)
        new_lst.append(avg_score)
    return new_lst

