                sum+=score
                cnt+=1
            elif late==1:
                sum+=score*0.9
                cnt+=1
            elif late==2:
                sum+=score*0.75
                cnt+=1
            elif late==3:
                sum+=score*0.5
                cnt+=1
            else:
                cnt+=1
                continue
        if cnt>0:
            avr.append(sum/cnt)
        else:
            avr.append(0)
    return avr

