    for first in first_names:
        for last in last_names:
            full_name = first + ' ' + last
            full_names.append(full_name)
    return full_names

def average_scores(l: list):
    average_grade = []
    for i in l:
        n = 0
        total = 0
        for j in i:
            if j[1] == 0:
                total += j[0]
            if j[1] == 1:
                total += j[0] * 0.9
            if j[1] == 2:
                total += j[0] * 0.75
            if j[1] == 3:
                total += j[0] * 0.5
            if j[1] >= 4:
                total += j[0] * 0
            n += 1
            average_grade.append(total/n)
    return average_grade

