            elif lst_of_lsts[i][a][1] == 2:
                average += lst_of_lsts[i][a][0] * 0.75
            elif lst_of_lsts[i][a][1] == 3:
                average += lst_of_lsts[i][a][0] * 0.50
            else:
                average += lst_of_lsts[i][a][1] * 0
        scores.append(average/len(lst_of_lsts[i]))
    return scores

