def average_scores(scores):
    penalty_rates = {
        0: 1.0,    
        1: 0.9,    
        2: 0.75,   
        3: 0.5,         
    }

    average=[]

    for student in scores:
        grade=0  

        for gr in student:
            if gr[1]>= 4:
                grade+=gr[0]*0.0
            else:
                grade+=gr[0]*penalty_rates[gr[1]] 

        avg=grade/len(student)
        average.append(avg)
    return average

