def average_prices (t):
    count = {}
    sums = {}
    for item, price in t:
        if item not in sums:
            sums[item] = price
            count[item] = 1
        else:
            sums[item] += price
            count[item] += 1
    averages = {}
    for item in sums:
        averages[item] = sums[item]/count[item]
    return averages
