def average_prices(t):
    total_price = {}
    for item in t:
        total_price.update({item[0]: 0})
    for item in t:
        if item in t:
            total_price[item[0]] += item[1]

    total_number = {}
    for item in t:
        total_number.update({item[0]: 0})
    for item in t:
        if item in t:
            total_number[item[0]] += 1

    average = total_price.copy()
    for key in average:
        average[key] /= total_number[key]

    return average

