    counts = {}
    for commodity, price in prices:
        if commodity not in total_prices:
            total_prices[commodity] = price
            counts[commodity] = 1
        else:
            total_prices[commodity] += price
            counts[commodity] += 1

    averages = {}
    for commodity in total_prices:
        averages[commodity] = total_prices[commodity] / counts[commodity]

    return averages

def count_bigrams(words):
