        avg[name] = totprice[name]/totnumber[name]
    return avg

def count_bigrams(lst):
    bigrams = {}
    for i, e in enumerate(lst):
        if i != len(lst) - 1:
            if ((e,lst[i+1])) not in bigrams:
                bigrams[(e,lst[i+1])] = 1
            else:
                bigrams[(e,lst[i+1])] += 1
        else:
            break
    return bigrams

