	Dict = {}
	Total_Dict = {}
	Number_Dict = {}
	Index = []
	for i in Tups:
		if i[0] in Total_Dict:
			Total_Dict[i[0]] += 1
		else:
			Total_Dict[i[0]] = 1
		if i[0] in Number_Dict:
			Number_Dict[i[0]].append(i[1])
		else:
			Number_Dict[i[0]] = []
			Number_Dict[i[0]].append(i[1])
			Index.append(i[0])
	for i in Index:
		Dict[i] = sum(Number_Dict[i]) / Total_Dict[i] 
