def average_prices(comm):
    # comm is an iterable of (key, price) pairs
    counts = {}
    totals = {}
    for entry in comm:
        index, price = entry
        counts[index] = counts.get(index, 0) + 1
        totals[index] = totals.get(index, 0.0) + price

    # compute averages per key
    avg_price = {}
    for index in totals:
        avg_price[index] = totals[index] / counts[index]
    return avg_price

