            price_dict[item[0]] = item[1]
        else:
            number_dict[item[0]] += 1
            price_dict[item[0]] += item[1]
    for good in price_dict:
        average_dict[good] = (price_dict[good] / number_dict[good])
    return average_dict

def count_bigrams(tup):
