def calc_avg_from_file():
    sum_ = 0.0
    count = 0
    with open("grades.txt", "r") as file:
        for line in file:
            line = line.strip()
            if not line:
                continue
            try:
                value = float(line)
            except ValueError:
                continue
            sum_ += value
            count += 1
    if count == 0:
        return 0.0
    return sum_ / count

