def print_stars_to_file(n):
    try:
        with open (f"stars_{n}.txt", "x") as g:
            g.close()
    except:
        print("file already exists")

    with open(f"stars_{n}.txt", "a") as f:
        f.truncate(0)
        for i in range(n,0,-1):
            f.write(" "*i)
            f.write("*" * (2*n+1 - 2*i))
            f.write("\n")

