def calc_avg_from_file():
	filename = "grades.txt"
	with open(filename, 'r', encoding='utf-8') as f:
		text = f.read()
	parts = text.split('\n') if text else []
	numbers = [float(s) for s in parts if s.strip() != ""]
	if not numbers:
		return 0.0
	return sum(numbers) / len(numbers)

