        schedules = sorted(self.schedules)
        for time in schedules:
            if time <= query_time: 
                target_temp = self.schedules[time]
            else:
                break
        return target_temp

def __str__(self):
        output = f"Default temperature: {self._default_temperature} degrees"
        sorted_schedules = sorted(self._schedules.items())

        for i, (time, temp) in enumerate(sorted_schedules):
            output += f"\n{time} {temp} degrees"

        return output

def __init__(self, default_temperature=68):
        self._default_temperature = default_temperature
        self._schedules = {}

def get_target_temperature(self, query_time):
        target_temp = self._default_temperature
        sorted_schedules = sorted(self._schedules.items())

        for time, temp in sorted_schedules:
            if time <= query_time:
                target_temp = temp
            else:
                break # Query time is before this schedule, so we found the latest applicable schedule
        return target_temp

def __str__(self):
        result = f"Default temperature: {self.default_temp} degrees"
        for time in sorted(self.schedules):
            result += f"\n{time} {self.schedules[time]} degrees"
        return result

def __init__(self, default_temp=68):
        self.default_temp = default_temp
        self.schedules = {}

def get_target_temperature(self, query_time):
        times = sorted(self.schedules)
        if not times:
            return self.default_temp
        last_time = None
        for t in times:
            if t <= query_time:
                last_time = t
            else:
                break
        if last_time is None:
            return self.default_temp
        return self.schedules[last_time]

def __str__(self):
        result = "Default temperature: " + str(self.temperature) + " degrees"

        for i in sorted(self.schedule):
            temperature = self.schedule[i] # i is the time
            result += "\n" + str(i) + " " + str(temperature) + " degrees"

        return result

