        self.temperature = temperature
        self.schedule = {}

def get_target_temperature(self, qtime):
        latest = self.temperature # initialized with the default value

        for i in sorted(self.schedule):
            if(i <= qtime):
                latest = self.schedule[i] # since it is a dictionary

        return latest

