        self.schedules = {}

def get_target_temperature(self, query_time):
        if not self.schedules:
            return self.default_temp

        times = sorted(self.schedules)

        if query_time < times[0]:
            return self.default_temp

        latest_time = None
        for t in times:
            if t <= query_time:
                latest_time = t
            else:
                break

        if latest_time is None:
            return self.default_temp

        return self.schedules[latest_time]

def __str__(self):
        result = f"Default temperature: {self.default_temp} degrees"

        if not self.schedules:
            return result

        for time in sorted(self.schedules):
            result += f"\n{time} {self.schedules[time]} degrees"

        return result

def __init__(self, default_temp = 68):
        self.default_temp = default_temp
        self.schedules = {}

def get_target_temperature(self, query_time):
        if not self.schedules:
            return self.default_temp

        times = sorted(self.schedules)

        if query_time < times[0]:
            return self.default_temp

        latest_time = None
        for t in times:
            if t <= query_time:
                latest_time = t
            else:
                break

        if latest_time is None:
            return self.default_temp

        return self.schedules[latest_time]

def __str__(self):
        final = [f"Default temperature: {self.default} degrees"]
        lst = sorted(self.schedules)
        for time in lst:
            temp = self.schedules[time]
            final.append(f"{time} {temp} degrees")
        return "\n".join(final)

def __init__(self, default=68):
        self.default = default
        self.schedules = {}

def get_target_temperature(self, q_time):
        hours, minutes = q_time.split(":")
        q_val = (int(hours) * 100) + int(minutes)
        if not self.schedules:
            return self.default
        lst = sorted(self.schedules)
        latest = self.default
        for time in lst:
            t_hours, t_minutes = time.split(":")
            t_val = (int(t_hours) * 100) + int(t_minutes)
            if t_val <= q_val:
                latest = self.schedules[time]
            else:
                break
        return latest

def __str__(self):
        result_lines = [f"Default temperature: {self.default_temp} degrees"]

        for t in sorted(self.schedules.keys()):
            result_lines.append(f"{t} {self.schedules[t]} degrees")

        return "\n".join(result_lines)

def __init__(self, default_temp=68):
        self.default_temp = default_temp
        self.schedules = {}

def get_target_temperature(self, query_time):
        if not self.schedules:
            return self.default_temp

        sorted_times = sorted(self.schedules.keys())

        if query_time < sorted_times[0]:
            return self.default_temp

        latest_valid_time = None
        for t in sorted_times:
            if t <= query_time:
                latest_valid_time = t
            else:
                break

        if latest_valid_time is None:
            return self.default_temp

        return self.schedules[latest_valid_time]

def __str__(self):
        lines = []
        lines.append(f"Default temperature: {self.default_temp} degrees")
        for t in sorted(self.schedules):
            temp = self.schedules[t]
            lines.append(f"{t} {temp} degrees")
        return "\n".join(lines)

def __init__(self, default_temp=68):
        self.default_temp = default_temp
        self.schedules = {}

def get_target_temperature(self, query_time):
        if not self.schedules:
            return self.default_temp
        times = sorted(self.schedules)
        last_time_before_or_equal = None
        for t in times:
            if t <= query_time:
                last_time_before_or_equal = t
            else:
                break
        if last_time_before_or_equal is None:
            return self.default_temp
        return self.schedules[last_time_before_or_equal]

def __str__(self):
        result = f"Default temperature: {self.default_temp} degrees"
        if self.schedules:
            sorted_times = sorted(self.schedules)
            for t in sorted_times:
                result += f"\n{t} {self.schedules[t]} degrees"
        return result

def __init__(self, default_temp=68):
        self.default_temp = default_temp
        self.schedules = {}

def get_target_temperature(self, query_time):
        if not self.schedules:
            return self.default_temp

        sorted_times = sorted(self.schedules)
        last_temp = self.default_temp

        for t in sorted_times:
            if t <= query_time:
                last_temp = self.schedules[t]
            else:
                break

        return last_temp

