def __init__(self, default_temp=68):
        self.default_temp = default_temp
        self.schedules = {}

def get_target_temperature(self, query_time):
        # if no schedules exist → return default temperature
        if len(self.schedules) == 0:
            return self.default_temp

        # get sorted list of times
        sorted_times = sorted(self.schedules)

        # find the latest time ≤ query_time
        latest = None
        for t in sorted_times:
            if t <= query_time:
                latest = t
            else:
                break

        # if query_time is earlier than the first schedule
        if latest is None:
            return self.default_temp

        # otherwise return the scheduled temperature
        return self.schedules[latest]

def __str__(self):

        result = f"Default temperature: {self.default_temp} degrees"
        if len(self.schedules) == 0:
            return result


        for time in sorted(self.schedules):
            temp = self.schedules[time]
            result += f"\n{time} {temp} degrees"

        return result

def __init__(self, default_temp=68):
        self.default_temp = default_temp
        self.schedules = {}

def get_target_temperature(self, query_time):
        if len(self.schedules) == 0:
            return self.default_temp

        times = sorted(self.schedules)

        if query_time < times[0]:
            return self.default_temp

        latest_time = None
        for t in times:
            if t <= query_time:
                latest_time = t
            else:
                break

        if latest_time is None:
            return self.default_temp

        return self.schedules[latest_time]

def __init__(self, temp:float = 68):
        self.default = temp
        self.schedule = {}

def get_target_temperature(self,time:str):
        if time in self.schedule:
            return self.schedule[time]
        else:
            temp = list(self.schedule.keys())
            temp.append(time)
            sort = sorted(temp, key=lambda time: [int(x) for x in time.split(":")])
            if sort.index(time) != 0:
                return self.schedule[sort[sort.index(time)-1]]
            else:
                return self.default

