        self.temperature = temperature
        self.schedules = {}

def get_target_temperature(self,time):
        if not self.schedules:
            return self.temperature
        sorted_times = sorted(self.schedules)
        if time < sorted_times[0]:
            return self.temperature
        last_time = sorted_times[0]   
        for t in sorted_times:
            if t <= time:
                last_time = t
            else:
                break
        return self.schedules[last_time]

def __init__(self, default_temp=68):
    self.default_temp = default_temp
    self.schedule = {}

def get_target_temperature(self, query_time):
    if not self.schedule:
      return self.default_temp

    times = sorted(self.schedule.keys())

    if query_time < times[0]:
        return self.default_temp

    for i in range(len(times)):
      if query_time > times[i]:
        return self.schedule[times[i-1]]

    return self.schedule[times[-1]]

