def funky(n):
    if n == 0 or n == 1:
        return 1
    if n % 2 == 0:
        return 2 * funky(n//2)
    else:
        return 1 + 2 * funky(n+1)

def max_recursive(lst):
    if len(lst) == 0:
        return 0
    if len(lst) == 1:
        return lst[0]

    max = max_recursive(lst[1:])
    if lst[0] > max:
        return lst[0]
    else:
        return max

def sum_lists_recursive(lst1, lst2):
    if len(lst1) == 0:
        return 0

    sum = sum_lists_recursive(lst1[1:], lst2[1:])
    return lst1[0] + lst2[0] + sum

