def funky(n):
    """
    Implements the recursive mathematical function described in the problem.
    """
    # Base Case 1: n = 0
    if n == 0:
        return 1

    # Base Case 2: n = 1
    if n == 1:
        return 2

    # Case A: n > 1
    if n > 1:
        # Recursive Step: funky(n-1) + funky(n-2)
        return funky(n - 1) + funky(n - 2)

    # Case B: n < 0
    # Use n = n + 2 to progress towards the base cases (n=0 or n=1)
    if n < 0:
        # Recursive Step: 1 + funky(n + 2) + funky(n + 3)
        return 1 + funky(n + 2) + funky(n + 3)

def funky(n):
    """
    Implements the recursive function f(n) defined in the lab image.
    """
    # Base Case: if n is 0 or 1
    if n == 0 or n == 1:
        return 1

    # Recursive Case: if n is an even number
    elif n % 2 == 0:
        return 2 * funky(n // 2)

    # Recursive Case: otherwise (n is odd and not 1)
    else:
        return 1 + 2 * funky(n + 1)

