def funky(n):
    """
    Implements the recursive funky function as defined in the problem.
    """
    # Base cases
    if n == 0:
        return 2
    elif n == 1:
        return 3

    # Recursive cases
    if n > 1:
        return 2 * funky(n - 1) - 3 * funky(n - 2)
    else:  # n < 0
        return 2 * funky(n + 2) - funky(n + 1)

