def funky(n):

    # Case 1: Base Case
    if n == 0 or n == 1:
        return 1

    elif n % 2 == 0:
        # Recursive step: 2 * f(n // 2)
        # We use integer division // as specified in the definition.
        return 2 * funky(n // 2)

    # Case 3: Otherwise (If n is an odd number, positive or negative)
    else:
        # Recursive step: 1 + 2 * f(n + 1)
        return 1 + 2 * funky(n + 1)

