def funky(n):
    """
    Recursive function defined by:
      f(n) = 1                     if n == 0 or n == 1
             2 * f(n//2)          if n is even
             1 + 2 * f(n+1)      otherwise (n odd)
    Works for positive and negative integers.
    """
    if n == 0 or n == 1:
        return 1
    if n % 2 == 0:
        return 2 * funky(n // 2)
    return 1 + 2 * funky(n + 1)

def max_recursive(lst):

    if not lst:
