def funky(n: int) -> int:
    """
    Implements the recursive function:
        f(0) = 1
        f(1) = 1
        f(n) = 2 * f(n // 2)        if n is even
        f(n) = 1 + 2 * f(n + 1)     otherwise (odd or negative odd)
    """
    # Base cases
    if n == 0 or n == 1:
        return 1

    # Even number rule
    if n % 2 == 0:
        return 2 * funky(n // 2)

    # Odd number rule (includes negative odd)
    return 1 + 2 * funky(n + 1)

