def permutations(lis):
    retlis = []
    if len(lis) == 1:
        return [lis]
    for i in range(len(lis)):
        front_item = lis[i]
        remaining = [li for li in lis if li != front_item]
        for a in permutations(remaining):
            b = [front_item] + a
            retlis.append(b)
    return retlis

