def funky(n):
    if n == 0:
        return 1
    if n == 1 or n == -1:
        return 1
    if n == 2 or n == -2:
        return 2

    if n > 2:
        return funky(n - 1) + 2*n - 4
    else:
        return funky(n + 1) + 2*abs(n) - 4

