def longest_zigzag_from_start(lst):
    if len(lst) < 2:
        return len(lst)

    length = 1 
    increasing = None

    for i in range(1, len(lst)):
        if lst[i] > lst[i - 1]:  # increasing
            if increasing is None or increasing is False:
                length += 1
                increasing = True
            else:
                break

        elif lst[i] < lst[i - 1]:  # decreasing
            if increasing is None or increasing is True:
                length += 1
                increasing = False
            else:
                break
        else:
            continue

    return length

def longest_zigzag_from_start(lst):
    if len(lst) < 2:
        return len(lst)

    lgth = 1 
    p_diff = 0 

    for i in range(1, len(lst)):
        diff = lst[i] - lst[i - 1]
        if diff == 0:
            break
        if p_diff == 0 or diff * p_diff < 0:
            lgth += 1
            p_diff = diff
        else:
            break
    return lgth

def zigzag_lengths_from_all_starts(lst):
    n = len(lst)
    result = []

    for start in range(n):
        if start == n - 1:
            result.append(1)
            continue

        length = 1
        prev_diff = 0

        for i in range(start + 1, n):
            diff = lst[i] - lst[i - 1]
            if diff == 0:
                break

            if prev_diff == 0 or diff * prev_diff < 0:
                length += 1
                prev_diff = diff
            else:
                break

        result.append(length)

    return result

def longest_zigzag_from_start(lst):
    if len(lst) < 2:
        return len(lst)
    x = lst[1] - lst[0]
    if x == 0:
        count = 1
    else:
        count = 2
    for i in range(2, len(lst)):
        y = lst[i] - lst[i-1]
        if y == 0:
            continue
        if x * y < 0:
            count +=1
        x = y
    return count

def zigzag_lengths_from_all_starts(lst):
    newLst = []
    for i in range(len(lst)):
        count = 0
        if i == len(lst) - 1:
            newLst.append(1)
            continue
        x = lst[i+1] - lst[i]
        if x == 0:
            newLst.append(1)
            continue
        count += 1
        for j in range(i+1, len(lst)-1):
            y = lst[j+1] - lst[j]
            if y == 0 or x * y > 0:
                break
            count += 1
            x = y
        newLst.append(count+1)
    return newLst

