def longest_zigzag_from_start(lst):
    n = len(lst)
    if n < 2:
        return n
    if lst[1] == lst[0]:
        return 1
    length = 2
    old_diff = lst[1] - lst[0]
    for i in range(2, n):
        new_diff = lst[i] - lst[i - 1]
        if new_diff == 0:
            break
        if (old_diff > 0 and new_diff < 0) or (old_diff < 0 and new_diff > 0):
            length += 1
            old_diff = new_diff
        else:
            break
    return length

def zigzag_lengths_from_all_starts(lst):
    lengths = []
    for i in range(len(lst)):
        sub_list = lst[i:]
        lengths.append(longest_zigzag_from_start(sub_list))
    return lengths

def longest_zigzag_from_start(lst):
    if len(lst) < 2:
        return len(lst)
    else:
        index = 1
        counter = 2
        for number in lst[1:-1]:
            if (number < lst[index - 1] and number < lst[index + 1]) or (number > lst[index - 1] and number > lst[index + 1]):
                counter += 1
            else:
                break
            index += 1
        return counter

def zigzag_lengths_from_all_starts(lst):
