def zigzag_lengths_from_all_starts(lst):
    x = []
    for i in range(len(lst)):
        if i == len(lst) - 1:
            x.append(1)
            continue
        length = 1
        difference1 = lst[i + 1] - lst[i]
        if difference1 == 0:
            x.append(1)
            continue
        length = 2
        for j in range(i + 2, len(lst)):
            difference2 = lst[j] - lst[j - 1]
            if (difference1 > 0 and difference2 < 0) or (difference1 < 0 and difference2 > 0):
                length += 1
                difference1 = difference2
            else:
                break
        x.append(length)
    return x

def longest_zigzag_from_start(lst):
    count = 2 # for first and last items, which are not checked but always count
    if len(lst) < 2:
        return len(lst)
    for index, item in enumerate(lst):
        if index == 0: # skip first item
            continue
        if index == len(lst) - 1:
            break
        previous = lst[index - 1]
        next = lst[index + 1]
        if (item < previous and item < next) or (item > previous and item > next):
            count += 1
        else:
            break
    return count

