def longest_zigzag_from_start(lst):
    if len(lst) < 2:
        return len(lst)
    length = 1
    up = None # direction

    for i in range(1, len(lst)):
        if lst[i] == lst[i - 1]:
            break
        sequence_go_up = lst[i] > lst[i - 1]
        if up is None or sequence_go_up != up: # change direction
            length += 1
            up = sequence_go_up # update direction
        else:
            break 
    return length

