def merge_dicts(d1, d2):
    """
    Merges two dictionaries.
    - If a key appears in both, sum their values.
    - Otherwise, keep the existing key-value.
    """
    merged = d1.copy()
    for key, value in d2.items():
        if key in merged:
            merged[key] += value
        else:
            merged[key] = value
    return merged

