def pyramid(n):
    final = []
    while n > 0:
        lst = []
        for i in range(1, n+1):
            lst.append(str(i))
        lst.reverse()
        result = " ".join(lst)
        #print(result) # debug: prints each result
        final.append(result)
        n += -1
    #print(final) # debug: prints list containing all results
    return "\n".join(final)

