            dict[x] += 1
        else:
            dict[x] = 1
    return max(dict.values())

def greet_user(users, user_id, default_lang="en", default_age=18):
    if user_id not in users:
        return "User not found."

    info = users[user_id]
    name = info.get("name", "User")
    lang = info.get("language", default_lang)
    age = info.get("age", default_age)

    greetings = {
        "en": ("Hello, {name}!", "Hey there, {name}!"),
        "es": ("Hola, {name}!", "¡Hola, pequeño/a {name}!"),
        "fr": ("Bonjour, {name}!", "Salut, {name}!")
    }

    adult_greet, child_greet = greetings.get(lang, greetings["en"])
    return child_greet.format(name=name) if age < 18 else adult_greet.format(name=name)

def most_frequent_element(lst):
    if not lst:
        return None

    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1

    # Return the element with the highest count
    return max(counts, key=counts.get)

def greet_user(users: "nested dict", user_id, **kwargs: "dict")-> "greeting string":
    if user_id not in users:
        return "User not found."
    # setup
    user = users[user_id]
    name = user["name"]
    # defining age
    if "age" in user:
        age = user["age"]
    else:
        try:
            age = kwargs["default_age"]
        except:
            age = 18
    if age >= 18:
        str_age = "adult"
    else:
        str_age = "child"
    # defining language
    if "language" in user:
        language = user["language"]
    else:
        try:
            language = kwargs["default_language"]
        except:
            language = "en"
    # greeting
    greeting = {"en": {"adult": f"Hello, {name}!", "child": f"Hey there, {name}!"}, "es": {"adult": f"Hola, {name}!", "child": f"¡Hola, pequeño/a {name}!"}, "fr": {"adult": f"Bonjour, {name}!", "child": f"Salut, {name}!"}}
    return greeting[language][str_age]

def most_frequent_element(lst:"list")-> "most common element":
    if lst == []:
        return None
    element_count = {}
    for element in lst:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1 
    for element in element_count:
        if element_count[element] == max(element_count.values()):
            return element

