def greet_user(users: dict, user_id: str, default_lang='en', default_age=18) -> str:
    if user_id not in users:
        return 'User not found.'
    target_user = users[user_id]
    if ('language' in target_user and target_user['language'] == 'en') or ('language' not in target_user and default_lang == 'en'):
        if default_age < 18 or ('age' in target_user and target_user['age'] < 18):
            return f'Hey there, {target_user["name"]}!'
        else:
            return f'Hello, {target_user["name"]}!'
    elif ('language' in target_user and target_user['language'] == 'es') or ('language' not in target_user and default_lang == 'es'):
        if default_age < 18 or ('age' in target_user and target_user['age'] < 18):
            return f'¡Hola, pequeño/a {target_user["name"]}!'
        else:
            return f'Hola, {target_user["name"]}!'
    elif ('language' in target_user and target_user['language'] == 'fr') or ('language' not in target_user and default_lang == 'fr'):
        if default_age < 18 or ('age' in target_user and target_user['age'] < 18):
            return f'Salut, {target_user["name"]}!'
        else:
            return f'Bonjour, {target_user["name"]}!'

def most_frequent_element(lst: list): 
    if lst == []:
        return None
    frequencies = {}
    same_frequency = []
    winner = 'dummy'
    for element in lst:
        if element in frequencies:
            frequencies[element] += 1
        else:
            frequencies[element] = 1
    for element in frequencies:
        if winner == 'dummy':
            winner = element
        elif frequencies[element] > frequencies[winner]:
            winner = element
        elif frequencies[element] == frequencies[winner]:
            same_frequency.append(element)
            if winner not in same_frequency:
                same_frequency.append(winner)
    if same_frequency != [] and same_frequency[0] > winner:
        return random.choice(same_frequency)
    return winner

def greet_user(users, user_id, default_lang="en", default_age=18):
  if user_id not in users:
    return "User not found."

  user_info = users[user_id]
  name = user_info.get("name", "User")
  language = user_info.get("language", default_lang)
  age = user_info.get("age", default_age)

  greetings = {
      "en": {"adult": "Hello, {name}!", "child": "Hey there, {name}!"},
      "es": {"adult": "Hola, {name}!", "child": "¡Hola, pequeño/a {name}!"},
      "fr": {"adult": "Bonjour, {name}!", "child": "Salut, {name}!"}
  }

  age_group = "child" if age < 18 else "adult"

  if language not in greetings:
      language = default_lang

  return greetings[language][age_group].format(name=name)

def most_frequent_element(input_list):
  if not input_list:
    return None

  element_counts = {}
  for element in input_list:
    element_counts[element] = element_counts.get(element, 0) + 1

  most_frequent = None
  max_count = -1

  for element, count in element_counts.items():
    if count > max_count:
      max_count = count
      most_frequent = element

  return most_frequent

def greet_user(users, user_id, default_lang = "en", default_age = 18):
    if(user_id not in users):
        return "User not found." # print will cause it to keep going
    else:
        user_info = users[user_id]
        # EX: {"name": "Alice", "language": "en", "age": 25}// user_id is ess. "key"

        if("name" in user_info):
            name = user_info["name"] # accesses "Alice"; the value for name
        else:
            name = "User" # default parameter

        if("language" in user_info):
            language = user_info["language"]
        else:
            language = default_lang

        if("age" in user_info):
            age = user_info["age"]
        else:
            age = default_age

        if(language == "en"):
            if(age < 18):
                greeting = "Hey there, " + str(name) + "!"
            else:
                greeting = "Hello, " + str(name) + "!"

        elif(language == "es"):
            if(age < 18):
                greeting = "¡Hola, pequeño/a " + str(name) + "!"
            else:
                greeting = "Hola, " + str(name) + "!"

        elif(language == "fr"):
            if(age < 18):
                greeting = "Salut, " + str(name) + "!"
            else:
                greeting = "Bonjour, " + str(name) + "!"

        else:
            greeting = "Hello, " + str(name) + "!"

    return greeting

