def greet_user(users, user_id, default_lang="en", default_age=18):
    if user_id not in users:
        return "User not found."
    info=users[user_id]

    name=info.get("name", "UnknownUser")
    lang=info.get("language", default_lang)
    age=info.get("age", default_age)

    templates={
        "en": {"adult": "Hello, {name}!","child": "Hey there, {name}!"},
        "es": {"adult": "Hola, {name}!","child": "¡Hola, pequeño/a {name}!"},
        "fr": {"adult": "Bonjour, {name}!","child": "Salut, {name}!"},
    }

    if lang not in templates:
        lang=default_lang if default_lang in templates else "en"

    kind="child" if age < 18 else "adult"
    return templates[lang][kind].format(name=name)

def most_frequent_element(items):
    L={}
    for element in items:
        if element in L:
            L[element]+=1
        else:
            L[element]=1
    M=None
    N=-1
    for i in items:
        c=L[i]
        if c>N:
            N=c
            M=i
    return M

    if not items:
        return None

def greet_user(users, user_id, default_lang="en", default_age=18):
    if user_id not in users:
        return "User not found."
    user = users[user_id]
    name = user.get("name", "User")
    lang = user.get("language", default_lang)
    age = user.get("age", default_age)
    greetings = {
        "en": ("Hello, {name}!", "Hey there, {name}!"),
        "es": ("Hola, {name}!", "¡Hola, pequeño/a {name}!"),
        "fr": ("Bonjour, {name}!", "Salut, {name}!")
    }
    adult_msg, child_msg = greetings.get(lang, greetings["en"])
    if age < 18:
        return child_msg.format(name=name)
    return adult_msg.format(name=name)

def most_frequent_element(lst):
    if not lst:
        return None
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1
    return max(counts, key=counts.get)

