def most_frequent_element(elements):
    the_dict = {item: elements.count(item) for item in elements}
    max_value = 0
    max_key = None
    for key in the_dict:
        try:
            if the_dict[key] > max_value:
                max_value = the_dict[key]
                max_key = key
        except UnboundLocalError:
            max_key
    return max_key

