def most_frequent_element(list):
    elements = {}
    for element in list:
        if list == []:
            return None
        if element not in elements:
            elements[element] = 1
        elif element in elements:
            elements[element] += 1
    return sorted(elements, key = elements.get, reverse = True)[0]

