def most_frequent_element(l):
    l1=[]
    l2={}
    if l==[]:
        return None
    else:
        for i in l:
            if i not in l1:
                l1.append(i)
        for i in l1:
            l2[i]=l.count(i)
        l3=sorted(l2.items(), key=lambda item:item[1])
        return l3[-1][0]

